style.css:
@-moz-document domain("egyptpost.org") {
body {
    font-family: "Tajawal", sans-serif !important;
    background-color: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* الهيدر */
  .o365cs-base.o365cst.o365cs-topnavBGColor-2 {
    background-color: #1e1e1e !important;
    color: #ffffff !important;
    border-bottom: 1px solid #333 !important;
  }

  /* اللينكات */
  a {
    color: #4caf50 !important;
    text-decoration: none !important;
  }
  a:hover {
    color: #81c784 !important;
    text-decoration: underline !important;
  }

  /* القوائم */
  .contextMenuPopup, .popupShadow {
    background-color: #1e1e1e !important;
    border: 1px solid #333 !important;
    box-shadow: 0 0 10px rgba(0,0,0,0.7) !important;
  }

  /* الأزرار */
  button, .o365buttonOutlined {
    background: #4caf50 !important;
    color: #fff !important;
    border: none !important;
    border-radius: 4px !important;
    padding: 6px 12px !important;
    transition: 0.3s !important;
  }
  button:hover, .o365buttonOutlined:hover {
    background: #388e3c !important;
  }

  /* صندوق الرسائل */
  .ms-bg-color-neutralLight, .ms-bg-color-white {
    background-color: #1e1e1e !important;
    color: #e0e0e0 !important;
  }
}
